"""Owner-local, inspectable actual strand comparison; never a photo overlay."""
import json,html
from pathlib import Path
root=Path('output/portrait-detail')
comparison=json.loads((root/'white/comparison.json').read_text(encoding='utf8'))
control=json.loads((root/'white/control.json').read_text(encoding='utf8'))
candidate=json.loads((root/'white/candidate.json').read_text(encoding='utf8'))
natural=json.loads((root/'natural/candidate.json').read_text(encoding='utf8'))
natural_comparison=json.loads((root/'natural/comparison.json').read_text(encoding='utf8'))
assert control['project']['instruction']['profile']==candidate['project']['instruction']['profile']
def rows():
    text=''
    for name,data in [('Old tonal target',control),('Separate contour target',candidate)]:
        i=data['project']['instruction'];text+=f"<tr><td>{name}</td><td>{i['metrics']['lines']}</td><td>{i['metrics']['estimatedMeters']:.2f} m</td><td>{data['evidence']['stageMs']/1000:.2f} s</td></tr>"
    return text
metrics=''
for row in comparison:
    a,b=row['variants']
    for key in ['eyes','nose','mouth','face']:
        x=a['originalTargetErrors'][key];y=b['originalTargetErrors'][key]
        metrics+=f"<tr><td>{row['resolution']}</td><td>{key}</td><td>{x['mse']:.6f} → {y['mse']:.6f}</td><td>{x['edgeMse']:.6f} → {y['edgeMse']:.6f}</td><td>{a['sourceContourCosine'][key]:.4f} → {b['sourceContourCosine'][key]:.4f}</td></tr>"
(root/'report.html').write_text('''<!doctype html><html lang="uz"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Ip Rasm — haqiqiy ipli portret</title><style>body{font:17px system-ui;margin:24px;max-width:1250px;color:#173f35;background:#faf8ef}section{display:flex;flex-wrap:wrap;gap:16px}figure{margin:0;width:30%;min-width:220px}img{width:100%;height:auto}p{line-height:1.6;max-width:100ch}table{border-collapse:collapse}th,td{padding:9px;border:1px solid #ccd5c7}a{color:#235544}.scroll{overflow:auto}code{overflow-wrap:anywhere}@media(max-width:650px){figure{width:100%}}</style>
<h1>Ipdan chizilgan yuz: tonal va kontur variantlari</h1><p>Ilovada <b>Portretni ustuvor hisoblash → Yuz konturlarini ajratish</b> ni yoqing, avval nishonni tekshirib, keyin yangi hisob yarating. Bu tanlov UZ/RU/EN va Android paketida mavjud. Eski variant va progress saqlanadi. <a href="http://127.0.0.1:4183/">Saytni sinash</a> · <a href="../mobile/ip-rasm-portrait-detail-debug.apk">Yangi APK</a>.</p>
<p><b>Konturlar ravshanroq; asl rang-soya yengilroq.</b> Yangi tayyorlash faqat suratdagi piksel detallaridan foydalanadi: tekis och joylarda kamroq qorayish, haqiqiy mayda qoramtir chiziqlarda kuchliroq ajralish. Yuz geometrisi yoki yangi anatomik chiziq yaratilmaydi. Pastdagi barcha natijalar haqiqiy butun mix-ulanishlarining optik rekonstruksiyasi, surat ustiga preview yopishtirilmagan. Burun hajmi, soya, soch va kesishgan iplar hali ideal emas. Bu bitta suratdagi alohida uslub; barcha suratlardagi eng yaxshi o‘xshashlik va fizik sifat tasdiqlanmagan. Standart tonal rejim o‘zgarmadi.</p>
<h2>Oq fonli original surat — yangi teng hisobli taqqoslash</h2><p>Ikkala yangi hisob bitta mahalliy tayyorlangan originaldan: bir xil crop, 240 aylana mix, 400 × 400 mm, 0.1 mm ip, 160 hisoblash nuqtasi, 32/160 cheklov, bo‘sh boshlang‘ich grafik va sakkizta butun-ip optimallashtirish bosqichi. Nishonning rang-soyasi o‘zgargan. Shuning uchun kamroq ulanishni “bir xil sifat saqlangan tejam” deb hisoblamaymiz. Vaqtlar desktop host o‘lchovlari, telefon yoki odam yig‘ish sinovi emas.</p>
<section><figure><img src="white/original-target-160.png" alt="Oq fonli tonal nishon"><figcaption>Asl tonal nishon</figcaption></figure><figure><img src="white/control-160.png" alt="Oldingi tonal ipli rekonstruksiya"><figcaption>Tonal nishondan haqiqiy iplar</figcaption></figure><figure><img src="white/candidate-160.png" alt="Yangi kontur nishonidan haqiqiy iplar"><figcaption>Kontur nishonidan haqiqiy iplar</figcaption></figure></section>
<div class="scroll"><table><tr><th>Variant</th><th>Ulanish</th><th>Taxminiy ip</th><th>To‘liq fit</th></tr>'''+rows()+'''</table></div>
<h2>Bir xil fizik doska/ipni 512 nuqtada qayta chizish</h2><p>Mayda iplarni kattalashtirganda kesishgan tekstura hali ko‘rinadi; nativ 160 preview bilan bu ko‘rinishni aralashtirmang. Barcha routing ulanishlari kiritilgan.</p><section><figure><img src="white/original-target-512.png" alt="Mustaqil original piksel nishoni"><figcaption>Originaldan mustaqil nishon</figcaption></figure><figure><img src="white/control-512.png" alt="Tonal variantning fizik umumiy rekonstruksiyasi"><figcaption>Tonal iplar</figcaption></figure><figure><img src="white/candidate-512.png" alt="Kontur variantning fizik umumiy rekonstruksiyasi"><figcaption>Kontur iplar</figcaption></figure></section>
<h2>Asl tonal nishonga qarshi ikkala o‘lchov</h2><p>Tone/edge MSE kichikroq bo‘lsa xato kamroq; signed contour cosine kattaroq bo‘lsa gradient yo‘nalishlari mosroq. Kontur usulida nose/lip edge MSE pasaydi va moslik oshdi, lekin <b>asl tone MSE oshdi</b>. Kosinusning 512 dagi mutlaq qiymatlari past; bu tanishlik yoki fizik sifat balli emas. Yangi nishonga qarshi alohida barcha o‘lchovlar JSONda ham bor.</p><div class="scroll"><table><tr><th>Nuqta</th><th>Joy</th><th>Asl tone MSE: old → new</th><th>Asl edge MSE</th><th>Signed contour cosine</th></tr>'''+metrics+'''</table></div>
<h2>Fonli suratda mustaqil taqqoslash</h2><p>Fonli oldgi sakkiz bosqichli control saqlangan, qayta hisoblangan deb ko‘rsatilmaydi. Yangi kontur nishoni sakkiz bosqich bilan yaratildi. 1768 → 1214 ulanish, 668.85 → 444.15 m; yana rang-soya o‘zgargani uchun quality-equivalent saving emas.</p><section><figure><img src="original-target-160.png" alt="Avvalgi fonli tonal target"><figcaption>Tonal nishon</figcaption></figure><figure><img src="control-160.png" alt="Saqlangan control"><figcaption>Saqlangan tonal iplar</figcaption></figure><figure><img src="candidate-160.png" alt="Yangi kontur iplar"><figcaption>Yangi alohida iplar</figcaption></figure></section>
<h2>Yo‘riqnoma va tekshiruv</h2><p>Oq fonli yangi guide: <code>04f33fcc75a572db17ff3f8d3e596701d4225cd04c49b8b70b9552535d23e261</code>. Uch tilning har bir PDF’i 32 sahifa, barcha 1044 tartibli qadam/hash/progress auditi va render ko‘rigi o‘tdi. EN shablonida 1440 koordinata/240 to‘liq mix raqami tekshirildi. Chop/yig‘ish hali tekshirilmagan. <a href="white/candidate-guide.json">Ilovaga import qilinadigan aynan shu loyiha</a> · <a href="white/comparison.json">O‘lchovlar</a> · <a href="build-evidence.json">APK auditi</a>.</p>
<p>124 unit/PDF testi o‘tdi. Browserdagi yangi rejim va o‘zgarmagan optical render uchun tekshiruvlar alohida JSON hisobotlarda: <a href="../portrait-detail-browser-final.json">Dastlab tuzatilgan tekshiruv</a> · <a href="../portrait-detail-browser-release.json">Oxirgi yangi rejim tekshiruvi</a>. Dastlab testlar noto‘g‘ri eksport nomi/avtomatik import-openni taxmin qilgan va tadqiqot JSONida project-envelope yetishmagan; to‘liq import qilinadigan guide alohida saqlandi, hech bir instruktsiya/hash o‘zgarmadi.</p>
<h2>Qabul qilinmagan tajriba ham saqlangan</h2><p>Kasrli log-density boshlang‘ich taqsimoti bir xil target/materialda ko‘z/burun/lab xatosini oshirdi. U ilovaga chiqarilmadi; <a href="../strand-relaxation/comparison.json">rad etilgan tajriba dalili</a> mahalliy saqlandi. Bu hujjat uning importini tavsiya qilmaydi. Telefon yangilash, real guruhlar, diverse portraits va fizik sifat ochiq. Hech narsa tashqariga yuklanmadi yoki publish/push qilinmadi.</p></html>''',encoding='utf8')
path=root/'report.html'
page=path.read_text(encoding='utf8')
natural_rows=''
for row in natural_comparison:
    a,b=row['variants']
    for key in ['eyes','nose','mouth','face']:
        x=a['originalTargetErrors'][key];y=b['originalTargetErrors'][key]
        natural_rows+=f"<tr><td>{row['resolution']}</td><td>{key}</td><td>{x['mse']:.6f} → {y['mse']:.6f}</td><td>{x['edgeMse']:.6f} → {y['edgeMse']:.6f}</td><td>{a['sourceContourCosine'][key]:.4f} → {b['sourceContourCosine'][key]:.4f}</td></tr>"
i=natural['project']['instruction']
section='''<h2>Yangi: asl soyani saqlaydigan kontur varianti</h2><p><b>Yuz konturlarini ajratish</b> yoqilganda <b>Asl soyani ko‘proq saqlash</b> belgilangan bo‘ladi. Uni o‘chirish pastdagi ancha och uslubni tanlaydi. Asl tonal rejim uchun ikkala tanlovni o‘chiring. Yangi usul bir tekis rangni o‘zgartirmaydi; mahalliy kontrast o‘zgarishi ko‘pi bilan 20/255 daraja. Bu ham boshqa target, boshqa haqiqiy ketma-ketlik.</p>
<p><b>Natija aralash, sifat hali qabul qilinmagan.</b> 160 nuqtada ko‘z/burun/labning tonal va kontur xatolari pasaydi. Bir xil fizik iplarni 512 nuqtada qayta chizganda kontur yo‘nalishi mosligi oshdi, lekin edge MSE biroz oshdi va lab/umumiy yuz tone MSE ham yomonlashdi. Burun/lab hajmi va ip kesishmalari hali zaif. Hech bir o‘lchov umumiy tanishlik yoki fizik sifat balli emas. Bir suratdan barcha mijozlar uchun eng zo‘r deb xulosa qilinmaydi.</p>'''
for n in [160,512]:
    section+=f'<section><figure><img src="natural/original-target-{n}.png" alt="Asl tonal nishon"><figcaption>Asl nishon · {n}</figcaption></figure><figure><img src="natural/control-{n}.png" alt="Tonal haqiqiy iplar"><figcaption>Control iplar</figcaption></figure><figure><img src="natural/candidate-{n}.png" alt="Soyani saqlovchi haqiqiy iplar"><figcaption>Yangi haqiqiy iplar</figcaption></figure></section>'
section+=f'<p>Control: 1356 ulanish / 526.89 m / 64.08 s. Yangi: {i["metrics"]["lines"]} ulanish / {i["metrics"]["estimatedMeters"]:.2f} m / {natural["evidence"]["stageMs"]/1000:.2f} s. Sakkizta fit bosqichi har ikkala hisobda; host yuklamasi teng bo‘lmagani uchun tezlik bo‘yicha nazoratli xulosa chiqarilmaydi. Bu variant ipni kamaytirmadi.</p>'
section+='<div class="scroll"><table><tr><th>Nuqta</th><th>Joy</th><th>Asl tone MSE: control → yangi</th><th>Asl edge MSE</th><th>Signed contour cosine</th></tr>'+natural_rows+'</table></div>'
section+=f'<p>Exact guide hash: <code>{i["sequenceHash"]}</code>. <a href="natural/candidate-guide.json">Aynan shu loyiha JSON</a> · <a href="natural/uz-guide.pdf">O‘zbekcha to‘liq PDF</a> · <a href="natural/comparison.json">Mustaqil o‘lchovlar</a>. PDF barcha 1406 tartibli qadam, hash va progress bo‘yicha tekshirildi; barcha sahifalar render qilindi. Chop etish/yig‘ish hali sinalmagan.</p>'
page=page.replace('<h2>Oq fonli original surat',section+'<h2>Oq fonli original surat',1)
page=page.replace('Konturlar ravshanroq; asl rang-soya yengilroq.','Ikki alohida kontur tayyorlash tanlovi mavjud. Yengilroq v1 rang-soyani ancha ochartiradi; v2 ko‘proq asl soyani saqlaydi.')
page=page.replace('124 unit/PDF testi o‘tdi.','124 unit/PDF testi o‘tdi; keyingi v2 qo‘shimchalari uchun uchta test qayta o‘tdi. Oxirgi sakkizta desktop/touch kontur va optical tekshiruvning barchasi bir yugurishda o‘tdi: <a href="../portrait-detail-natural-browser.json">yakuniy brauzer hisoboti</a>.')
path.write_text(page,encoding='utf8')
print('Local quality comparison records mixed natural-detail evidence and v1 tone losses; no physical acceptance.')
